// Get intelligence for an industry, with fuzzy matching
export function getIndustryIntelligence(industry) {
  if (!industry) return null;
  const direct = INDUSTRY_INTELLIGENCE[industry];
  if (direct) return direct;
  // Try case-insensitive match
  const key = Object.keys(INDUSTRY_INTELLIGENCE).find(k =>
    k.toLowerCase() === industry.toLowerCase()
  );
  return key ? INDUSTRY_INTELLIGENCE[key] : null;
}

// Get all available industry names
export function getIntelligenceIndustries() {
  return Object.keys(INDUSTRY_INTELLIGENCE);
}